  const mix = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = rnd(i + 1); const t = a[i]; a[i] = a[j]; a[j] = t; } return a; };
  const fill = (s, d) => s.replace(/\{(\w+)\}/g, (m, k) => (d[k] != null ? d[k] : m));
