  /* взвешенный выбор без повторов */
  const takeW = (arr, w) => { let sum = 0; arr.forEach(x => { sum += w(x); }); let r = Math.random() * sum; for (let i = 0; i < arr.length; i++) { r -= w(arr[i]); if (r <= 0) return arr.splice(i, 1)[0]; } return arr.pop(); };

  const FRIENDS = [{ n: 'Саша', i: 'Сашей' }, { n: 'Маша', i: 'Машей' }, { n: 'Тимур', i: 'Тимуром' }, { n: 'Аня', i: 'Аней' }, { n: 'Лёва', i: 'Лёвой' }, { n: 'Вика', i: 'Викой' }, { n: 'Миша', i: 'Мишей' }, { n: 'Соня', i: 'Соней' }, { n: 'Артём', i: 'Артёмом' }, { n: 'Полина', i: 'Полиной' }, { n: 'Даня', i: 'Даней' }, { n: 'Ева', i: 'Евой' }];
